P_{5}&P_{1}\end{bmatrix} \displaystyle=\sqrt{C_{0}(P_{1},P_{2},P_{3})C_{0}(P_{1},P_{5},P_{6})C_{0}(P_{2},P_{4},P_{6})C_{0}(P_{3},P_{4},P_{5})} \displaystyle\qquad\times\begin{Bmatrix}P_{1}&P_{2}&P_{3}\\
P_{4}&P_{5}&P_{6}\end{Bmatrix}\ . $$

The symbol $\{\begin{smallmatrix}P_{1}&P_{2}&P_{3}\\ P_{4}&P_{5}&P_{6}\end{smallmatrix}\}$ is the crossing kernel for sphere four-point function conformal blocks in the Racah-Wigner normalization [17], which we also call the Virasoro 6j-symbol. It has the correct tetrahedral symmetry as required by the picture, where the vertices of the tetrahedron are formed by $(P_{1},P_{2},P_{3})$ , $(P_{1},P_{5},P_{6})$ , $(P_{2},P_{4},P_{6})$ and $(P_{3},P_{4},P_{5})$ .

Thus the prediction of the volume conjecture is now that

$$ 2\,\text{vol}(\eta_{1},\eta_{2},\eta_{3},\eta_{4},\eta_{5},\eta_{6})=-2\pi\lim_{b\to 0}b^{2}\log\begin{Bmatrix}\frac{iQ}{2}-\frac{i\eta_{1}}{2\pi b}&\frac{iQ}{2}-\frac{i\eta_{2}}{2\pi b}&\frac{iQ}{2}-\frac{i\eta_{3}}{2\pi b}\\
\frac{iQ}{2}-\frac{i\eta_{4}}{2\pi b}&\frac{iQ}{2}-\frac{i\eta_{5}}{2\pi b}&\frac{iQ}{2}-\frac{i\eta_{6}}{2\pi b}\end{Bmatrix}\ , $$

where the volume on the left hand side is the volume of the hyperbolic tetrahedron specified by the dihedral angles $\eta_{j}$ .

One can evaluate the integral in the defining formula for the crossing kernel via saddle-point approximation in this limit and confirm that it agrees with the volume formula for a hyperbolic tetrahedron. This was done in [17], but the volume conjecture gives a conceptual derivation of that fact.

We also mention that the Virasoro crossing kernel has the following Regge symmetry [25, 26]

$$ \mathbb{F}_{P_{3},P_{6}}\!\begin{bmatrix}P_{4}&P_{2}\\
P_{5}&P_{1}\end{bmatrix}=\mathbb{F}_{P_{3},P_{6}}\!\begin{bmatrix}\frac{1}{2}(P_{2}+P_{4}+P_{5}-P_{1})&\frac{1}{2}(P_{1}+P_{2}+P_{4}-P_{5})\\
\frac{1}{2}(P_{1}+P_{4}+P_{5}-P_{2})&\frac{1}{2}(P_{1}+P_{2}+P_{5}-P_{4})\end{bmatrix}\ . $$

This implies via the volume conjecture that the volume of a hyperbolic tetrahedron is invariant under the replacement

$$ \displaystyle\theta_{1} \displaystyle\to\tfrac{1}{2}(\theta_{1}+\theta_{2}+\theta_{4}-\theta_{5})\ , \displaystyle\theta_{5} \displaystyle\to\tfrac{1}{2}(-\theta_{1}+\theta_{2}+\theta_{4}+\theta_{5})\ , \displaystyle\theta_{2} \displaystyle\to\tfrac{1}{2}(\theta_{1}+\theta_{2}+\theta_{5}-\theta_{4})\ , \displaystyle\theta_{4} \displaystyle\to\tfrac{1}{2}(\theta_{1}-\theta_{2}+\theta_{4}+\theta_{5})\ , $$

with $\theta_{3}$ and $\theta_{6}$ unchanged. This property is very non-trivial to see geometrically and giving a direct proof of it is rather hard.

